  device,
  "left",
  "upper",
  n,
  n,
  1,
  A,
  lda,
  B,
  lda,
  0,
  C,
  lda,
);
console.log("C = A*I = the full symmetric A =");
console.table([result.slice(0, 3), result.slice(3, 6), result.slice(6, 9)]); // [[2,1,0],[1,2,1],[0,1,2]]

if (typeof process !== "undefined") cleanup();
